package br.casasala.painel;
import android.media.*;import java.net.*;import java.io.*;import java.util.UUID;import java.util.concurrent.*;import org.json.*;
/** Foreground, opt-in microphone stream. No file recordings; bounded RAM/backpressure. */
public final class VoiceCapture{
 public interface Listener{void state(String value);void text(String value);void error(String value);}
 private volatile boolean running;private volatile int generation;private volatile long quietUntil;private AudioRecord recorder;private volatile HttpURLConnection connection;private final Listener listener;private final ArrayBlockingQueue<byte[]> chunks=new ArrayBlockingQueue<byte[]>(8);private String base,token,session;
 public VoiceCapture(Listener l){listener=l;}public boolean running(){return running;}
 public synchronized void start(String address,String secret)throws Exception{if(running)return;URL u=new URL(address);if(!u.getProtocol().equals("http")||u.getUserInfo()!=null||u.getQuery()!=null||u.getRef()!=null)throw new Exception("Use o endereço HTTP local da ponte de voz.");if(secret.length()<24||secret.indexOf('\n')>=0||secret.indexOf('\r')>=0)throw new Exception("Importe a chave da ponte de voz.");base=address.replaceAll("/+$","");token=secret;session=UUID.randomUUID().toString();int min=AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);if(min<=0)throw new Exception("O microfone não oferece áudio de 16 kHz neste aparelho.");recorder=new AudioRecord(MediaRecorder.AudioSource.MIC,16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(min*2,65536));if(recorder.getState()!=AudioRecord.STATE_INITIALIZED){recorder.release();recorder=null;throw new Exception("Não foi possível abrir o microfone.");}recorder.startRecording();chunks.clear();quietUntil=0;running=true;final int stamp=++generation;final AudioRecord own=recorder;new Thread(new Runnable(){public void run(){capture(stamp,own);}},"painel-mic").start();new Thread(new Runnable(){public void run(){send(stamp);}},"painel-voz").start();}
 public void hush(long ms){quietUntil=System.currentTimeMillis()+ms;chunks.clear();}
 public synchronized void stop(){running=false;generation++;HttpURLConnection c=connection;if(c!=null)c.disconnect();chunks.clear();if(recorder!=null){try{recorder.stop();}catch(Exception ignored){} } }
 private boolean live(int stamp){return running&&stamp==generation;}
 private void capture(int stamp,AudioRecord own){try{while(live(stamp)){byte[] data=new byte[30720];int off=0;while(live(stamp)&&off<data.length){int n=own.read(data,off,data.length-off);if(n<=0)throw new IOException("Leitura do microfone indisponível.");off+=n;}if(!live(stamp))break;if(System.currentTimeMillis()<quietUntil)continue;if(!chunks.offer(data))throw new IOException("A ponte está lenta. A voz foi pausada; confira a conexão.");}}catch(Exception e){if(live(stamp)){listener.error(e.getMessage());stop();}}finally{own.release();synchronized(this){if(recorder==own)recorder=null;}}}
 private void send(int stamp){try{while(live(stamp)){byte[] data=chunks.poll(1,TimeUnit.SECONDS);if(data==null)continue;HttpURLConnection c=(HttpURLConnection)new URL(base+"/v1/audio?session="+session).openConnection();connection=c;c.setConnectTimeout(4000);c.setReadTimeout(30000);c.setRequestMethod("POST");c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Content-Type","application/octet-stream");c.setDoOutput(true);c.setFixedLengthStreamingMode(data.length);try{OutputStream out=c.getOutputStream();out.write(data);out.close();if(c.getResponseCode()!=200)throw new IOException(c.getResponseCode()==401?"Chave da ponte de voz incorreta.":"A ponte de voz não está pronta. Teste em Ajustes.");ByteArrayOutputStream bytes=new ByteArrayOutputStream();InputStream in=c.getInputStream();byte[] b=new byte[1024];int n;while((n=in.read(b))!=-1){if(bytes.size()+n>8192)throw new IOException("Resposta de voz inválida.");bytes.write(b,0,n);}in.close();JSONObject result=new JSONObject(new String(bytes.toByteArray(),"UTF-8"));if(!live(stamp))break;String text=result.optString("text");if(text.length()>0){hush(1800);listener.text(text);}else listener.state(result.optString("state","idle"));}finally{c.disconnect();if(connection==c)connection=null;}}}catch(Exception e){if(live(stamp)){listener.error(e.getMessage()==null?"Sem conexão com a ponte de voz.":e.getMessage());stop();}}}
}
